def main(out):
    doc = {'lane': 'ODOO', 'rows': ROWS}
    Path(out).write_text(json.dumps(doc, ensure_ascii=False, indent=1) + '\n', encoding='utf-8')
    print(len(ROWS), 'rows ->', out)


if __name__ == '__main__':
    main(sys.argv[1])
